use vstd::prelude::*;

verus! {

    /// flipud takes a vector of f32 and returns a new vector
    /// with the same elements in reverse order.
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // the output has the same length as the input
            result.len() == m.len(),
            // for every valid index i, result[i] == m[n - 1 - i]
            forall |i: nat|
                i < m.len()
                ==> result[i] == m[m.len() - 1 - i]
    {
        let n: usize = m.len();
        let mut res: Vec<f32> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == i,
                // the first i elements of res are exactly the last i elements of m
                forall |k: nat|
                    k < res.len()
                    ==> res[k] == m[n - 1 - k],
            decreases n - i,
        {
            let idx: usize = n - 1 - i;
            res.push(m[idx]);
            i += 1;
        }
        res
    }
}

